def fetch(url):
    if url == 'bad://x':
        raise ValueError('boom')
    return url.upper()

results, errors = gather(['a://1', 'bad://x', 'b://2', 'c://3'], fetch, workers=2)
assert results == {'a://1': 'A://1', 'b://2': 'B://2', 'c://3': 'C://3'}, f'results: {results}'
assert errors == {'bad://x': 'boom'}, f'errors: {errors}'
print('ok')

results, errors = gather([], lambda u: u)
assert results == {} and errors == {}
print('ok')
